using Npgsql;
using SharedKernel.Application;
namespace SharedKernel.Infrastructure;
public sealed partial class PostgresMaterialAttributeCatalog
{
    private async Task EnsureUnused(string group,string? field,NpgsqlConnection connection,NpgsqlTransaction tx,CancellationToken ct)
    {
        await using var check=new NpgsqlCommand(field is null?"SELECT EXISTS(SELECT 1 FROM product_lifecycle.urun_agaci_kalem WHERE material_group_code=@group) OR EXISTS(SELECT 1 FROM product_lifecycle.urun WHERE material_group_code=@group)":"SELECT EXISTS(SELECT 1 FROM product_lifecycle.urun_agaci_kalem WHERE material_group_code=@group AND attributes ? @field) OR EXISTS(SELECT 1 FROM product_lifecycle.urun WHERE material_group_code=@group AND attributes ? @field)",connection,tx);
        check.Parameters.AddWithValue("group",group);if(field is not null)check.Parameters.AddWithValue("field",field);if((bool)(await check.ExecuteScalarAsync(ct))!)throw new DefinitionInUseException();
    }
    public async Task<MaterialGroupDto> UpdateGroupAsync(string code,string name,CancellationToken ct)
    {code=MaterialAttributeRules.Code(code);name=DefinitionInput.Required(name,"name");await using var connection=await source.OpenConnectionAsync(ct);await using var tx=await connection.BeginTransactionAsync(ct);await EnsureUnused(code,null,connection,tx,ct);await using var cmd=new NpgsqlCommand("UPDATE shared_definitions.material_group SET name=@name WHERE code=@code",connection,tx);cmd.Parameters.AddWithValue("code",code);cmd.Parameters.AddWithValue("name",name);if(await cmd.ExecuteNonQueryAsync(ct)==0)throw new UnknownDefinitionCategoryException();await tx.CommitAsync(ct);return (await ListAsync(ct)).Single(g=>g.Code==code);}
    public async Task DeleteGroupAsync(string code,CancellationToken ct)
    {code=MaterialAttributeRules.Code(code);await using var connection=await source.OpenConnectionAsync(ct);await using var tx=await connection.BeginTransactionAsync(ct);await EnsureUnused(code,null,connection,tx,ct);await using var cmd=new NpgsqlCommand("DELETE FROM shared_definitions.material_attribute_definition WHERE group_code=@code;DELETE FROM shared_definitions.material_group WHERE code=@code",connection,tx);cmd.Parameters.AddWithValue("code",code);if(await cmd.ExecuteNonQueryAsync(ct)==0)throw new UnknownDefinitionCategoryException();await tx.CommitAsync(ct);}
    public async Task<MaterialAttributeDefinition> UpdateFieldAsync(string group,string code,string name,string? unit,CancellationToken ct)
    {group=MaterialAttributeRules.Code(group);code=MaterialAttributeRules.Code(code);name=DefinitionInput.Required(name,"name");unit=string.IsNullOrWhiteSpace(unit)?null:DefinitionInput.Required(unit,"unit");await using var connection=await source.OpenConnectionAsync(ct);await using var tx=await connection.BeginTransactionAsync(ct);await EnsureUnused(group,code,connection,tx,ct);await using var cmd=new NpgsqlCommand("UPDATE shared_definitions.material_attribute_definition SET name=@name,unit=@unit WHERE group_code=@group AND code=@code RETURNING data_type",connection,tx);cmd.Parameters.AddWithValue("group",group);cmd.Parameters.AddWithValue("code",code);cmd.Parameters.AddWithValue("name",name);cmd.Parameters.Add("unit",NpgsqlTypes.NpgsqlDbType.Text).Value=(object?)unit??DBNull.Value;var type=await cmd.ExecuteScalarAsync(ct) as string??throw new UnknownDefinitionCategoryException();await tx.CommitAsync(ct);return new(code,name,type,unit);}
    public async Task DeleteFieldAsync(string group,string code,CancellationToken ct)
    {group=MaterialAttributeRules.Code(group);code=MaterialAttributeRules.Code(code);await using var connection=await source.OpenConnectionAsync(ct);await using var tx=await connection.BeginTransactionAsync(ct);await EnsureUnused(group,code,connection,tx,ct);await using var cmd=new NpgsqlCommand("DELETE FROM shared_definitions.material_attribute_definition WHERE group_code=@group AND code=@code",connection,tx);cmd.Parameters.AddWithValue("group",group);cmd.Parameters.AddWithValue("code",code);if(await cmd.ExecuteNonQueryAsync(ct)==0)throw new UnknownDefinitionCategoryException();await tx.CommitAsync(ct);}
}
